masks=[(r,c) for r in range(30) for c in range(30) if grid[r][c]==6]
amb=[]
for r,c in masks:
    opts=[]
    if grid[c][r]!=6: opts.append(('diag',grid[c][r]))
    if 31-r<30 and grid[31-r][c]!=6: opts.append(('horiz',grid[31-r][c]))
    if not opts: amb.append((r,c,grid[c][r],grid[31-r][c] if 31-r<30 else None))
len(masks),len(amb),amb

from collections import deque
out=[row[:] for row in grid]
def orbit_val(r,c):
    seen={(r,c)}; q=deque([(r,c)])
    while q:
        a,b=q.popleft()
        if grid[a][b]!=6:return grid[a][b],(a,b)
        cand=[(b,a)]
        if a>=2: cand.append((31-a,b))
        for x in cand:
            if 0<=x[0]<30 and x not in seen:
                seen.add(x);q.append(x)
    return None,seen
un=[]; sources={}
for r,c in masks:
    val,src=orbit_val(r,c)
    if val is None:un.append((r,c,src))
    else:out[r][c]=val;sources[(r,c)]=src
len(un),un[:10],[(p,sources[p],out[p[0]][p[1]]) for p in [(15,5),(16,5),(5,15),(5,16)]]
